    std::unique_ptr<Texture> createTexture(const TextureDesc& desc) override {
        if (!allowTextureCreation) return nullptr;
        lastTextureDesc = desc;
        ++createdTextureCount;
        return std::make_unique<DummyTexture>(desc.width, desc.height);
    }
