void testTilesetRasterMoreDetailCreatesUpsampledChildren() {
    auto overlay = std::make_unique<RasterOverlay>(
        std::make_unique<DebugImageryProvider>(),
        TileScheme::createXYZWebMercator(),
        makeRasterOverlayOptions());
    ActivatedRasterOverlay activated(*overlay);
    auto terrainProvider = std::make_unique<SparseTerrainProvider>();
    auto scheme = TileScheme::createGeographicTMS();
    Tileset tileset = TilesetTestAccess::makeLegacyTerrainTileset(
        std::move(terrainProvider),
        std::move(scheme),
        {&activated},
        nullptr,
        TilesetOptions{});
    const TileKey rootKey{"Geographic-TMS", 0, 0, 0};
    TilesetTile* root = TilesetTestAccess::ensureTile(tileset, rootKey);
    check(root != nullptr,
          "Tileset: raster-more-detail root tile is created");
    if (!root) return;
    const Rectangle contentRectangle =
        Rectangle::fromDegrees(-20.0, -10.0, 0.0, 10.0);
    const Rectangle overlayRectangle =
        Rectangle::fromDegrees(-30.0, -40.0, 10.0, 60.0);
    root->bounds = contentRectangle;
    root->content.renderContent.setSurfaceMesh(std::make_unique<SurfaceTileMesh>());
    RasterOverlayDetails rasterDetails;
    rasterDetails.rasterOverlayProjections = {
        RasterOverlayProjection::WebMercator};
    rasterDetails.rasterOverlayRectangles = {
        projectRectangleSimple(
            WebMercatorProjection(Ellipsoid::WGS84()),
            overlayRectangle)};
    rasterDetails.boundingRegion = {contentRectangle, 0.0, 0.0};
    root->content.renderContent.mutableSurfaceMesh()->rasterOverlayDetails =
        rasterDetails;
    root->content.renderContent.setMeshReady(true);
    root->content.renderContent.setSurfaceGpuBuffers(
        std::make_unique<DummyBuffer>(32),
        nullptr);
    root->geometricError = 100.0;
    root->content.loadState = TileLoadState::Done;
    root->content.contentKind = TileContentKind::Render;
    root->rasterOverlayState.mappings().resize(1);
    Renderer renderer(nullptr);
    RenderCommandList commands;
    TilesetTestAccess::buildTileDrawCommand(
        tileset,
        renderer,
        *root,
        commands,
        1.0f);
    RasterMappedToTilesetTile* mapped = root->rasterOverlayState.mappings()[0].get();
    RasterOverlayTile* loadingTile = mapped ? mapped->getLoadingTile() : nullptr;
    check(loadingTile != nullptr,
          "Tileset: raster-more-detail loading tile is mapped");
    if (!loadingTile) return;
    loadingTile->setTexture(std::make_unique<DummyTexture>(4, 4));
    loadingTile->setMoreDetailAvailable(
        RasterOverlayTile::MoreDetailAvailable::Yes);
    commands.clear();
    TilesetTestAccess::buildTileDrawCommand(
        tileset,
        renderer,
        *root,
        commands,
        1.0f);
    check(root->children.size() == 4,
          "Tileset: raster more detail creates four upsampled children");
    check(TilesetTestAccess::canRefine(tileset, *root),
          "Tileset: raster upsampled children make parent refinable");
    bool allUpsampled = root->children.size() == 4;
    for (TilesetTile* child : root->children) {
        allUpsampled &= child && child->content.isRasterDetailUpsample() &&
            child->parent == root &&
            std::abs(child->geometricError - 50.0) < 1e-9 &&
            child->boundingVolume &&
            child->boundingVolume->kind == TileBoundingVolumeKind::Region;
    }
    check(allUpsampled,
          "Tileset: raster more-detail children carry upsample metadata and region bounds");
    const Rectangle expectedRegion =
        contentRectangle.computeUnion(overlayRectangle);
    const auto projectedCenter =
        rasterDetails.rasterOverlayRectangles[0].center();
    const Cartographic center = unprojectPosition(
        WebMercatorProjection(Ellipsoid::WGS84()),
        Vec3(projectedCenter.first, projectedCenter.second, 0.0));
    const std::array<Rectangle, 4> expectedChildBounds{
        Rectangle(
            expectedRegion.west(),
            expectedRegion.south(),
            center.longitude(),
            center.latitude()),
        Rectangle(
            center.longitude(),
            expectedRegion.south(),
            expectedRegion.east(),
            center.latitude()),
        Rectangle(
            expectedRegion.west(),
            center.latitude(),
            center.longitude(),
            expectedRegion.north()),
        Rectangle(
            center.longitude(),
            center.latitude(),
            expectedRegion.east(),
            expectedRegion.north())};
    auto rectangleNear = [](const Rectangle& a, const Rectangle& b) {
        constexpr double epsilon = 1e-12;
        return std::abs(a.west() - b.west()) < epsilon &&
            std::abs(a.south() - b.south()) < epsilon &&
            std::abs(a.east() - b.east()) < epsilon &&
            std::abs(a.north() - b.north()) < epsilon;
    };
    bool hasExpectedChildBounds = root->children.size() == 4;
    for (const Rectangle& expected : expectedChildBounds) {
        hasExpectedChildBounds =
            hasExpectedChildBounds &&
            std::any_of(
                root->children.begin(),
                root->children.end(),
                [&](const TilesetTile* child) {
                    return child && rectangleNear(child->bounds, expected);
                });
    }
    check(hasExpectedChildBounds,
          "Tileset: raster more-detail children split the Cesium-native content/overlay union at projection center");
}
void testTilesetGltfRenderContentBuildsPrimitiveCommands() {
    DummyRenderDevice device;
    device.allowTextureCreation = true;
    auto scheme = TileScheme::createGeographicTMS();
    Tileset tileset(
        std::move(scheme),
        {},
        &device,
        TilesetOptions{});
    const TileKey rootKey{"Geographic-TMS", 0, 0, 0};
    TilesetTile* root = TilesetTestAccess::ensureTile(tileset, rootKey);
    check(root != nullptr,
          "Tileset: glTF render-content root tile is created");
    if (!root) return;
    root->content.renderContent.prepareGltfContent(
        makeTexturedTriangleGltfModel(),
        Mat4::identity());
    root->content.contentKind = TileContentKind::Render;
    root->content.loadState = TileLoadState::ContentLoaded;
    Renderer renderer(nullptr);
    RenderCommandList commands;
    TilesetTestAccess::buildTileDrawCommand(
        tileset,
        renderer,
        *root,
        commands,
        0.5f);
    check(!root->content.renderContent.isMeshReady() &&
              root->content.renderContent.isGltfRenderReady() &&
              root->content.renderContent.isRenderContentReady() &&
              root->content.loadState == TileLoadState::Done,
          "Tileset: glTF render content reaches ready state after resource upload");
    check(!root->content.renderContent.hasSurfaceMesh() &&
              root->content.renderContent.surfaceVertexBuffer() == nullptr,
          "Tileset: glTF render content does not synthesize terrain mesh resources");
    check(root->content.renderContent.gltfPrimitiveResourceCount() == 1,
          "Tileset: glTF render content creates one primitive resource set");
    check(device.createdTextureCount == 1,
          "Tileset: glTF baseColorTexture is uploaded as a GPU texture");
    check(device.lastTextureDesc.width == 1 &&
              device.lastTextureDesc.height == 1 &&
              device.lastTextureDesc.wrapS == TextureDesc::Wrap::MirroredRepeat &&
              device.lastTextureDesc.wrapT == TextureDesc::Wrap::Clamp,
          "Tileset: glTF sampler state is preserved when uploading texture");
    check(commands.size() == 1,
          "Tileset: glTF render content emits one primitive draw command");
    if (commands.empty()) return;
    const RenderCommand& cmd = commands.front();
    check(cmd.kind == RenderCommandKind::GltfPrimitive,
          "Tileset: glTF draw command uses the GltfPrimitive kind");
    check(cmd.vertexStride == 120 && cmd.indexCount == 3 &&
              cmd.vertexCount == 3,
          "Tileset: glTF draw command preserves primitive geometry counts");
    const GltfPrimitiveRenderResources* primitiveResources =
        root->content.renderContent.gltfPrimitiveResourceForReadAt(0);
    check(cmd.vertexBuffer ==
              (primitiveResources ? primitiveResources->vertexBuffer.get() : nullptr) &&
              cmd.indexBuffer ==
              (primitiveResources ? primitiveResources->indexBuffer.get() : nullptr),
          "Tileset: glTF draw command references primitive render resources");
    const auto* uploadedVertices =
        dynamic_cast<const DummyBuffer*>(cmd.vertexBuffer);
    check(uploadedVertices && uploadedVertices->size() == 3u * 120u,
          "Tileset: glTF vertex buffer uses multi-UV/COLOR_0/TANGENT layout bytes");
    bool firstVertexSecondUvUploaded = false;
    bool firstVertexColorUploaded = false;
    bool firstVertexTangentUploaded = false;
    if (uploadedVertices && uploadedVertices->bytes().size() >= 120u) {
        std::array<float, 30> values{};
        std::memcpy(
            values.data(),
            uploadedVertices->bytes().data(),
            values.size() * sizeof(float));
        firstVertexSecondUvUploaded =
            std::abs(values[8] - 0.25f) < 1e-6f &&
            std::abs(values[9] - 0.75f) < 1e-6f;
        firstVertexColorUploaded =
            std::abs(values[10] - 0.25f) < 1e-6f &&
            std::abs(values[11] - 0.5f) < 1e-6f &&
            std::abs(values[12] - 0.75f) < 1e-6f &&
            std::abs(values[13] - 1.0f) < 1e-6f;
        firstVertexTangentUploaded =
            std::abs(values[14] - 1.0f) < 1e-6f &&
            std::abs(values[15] - 0.0f) < 1e-6f &&
            std::abs(values[16] - 0.0f) < 1e-6f &&
            std::abs(values[17] - 1.0f) < 1e-6f;
    }
    check(firstVertexSecondUvUploaded,
          "Tileset: glTF GPU vertices include TEXCOORD_1 values");
    check(firstVertexColorUploaded,
          "Tileset: glTF GPU vertices include COLOR_0 values");
    check(firstVertexTangentUploaded,
          "Tileset: glTF GPU vertices include TANGENT values");
    check(cmd.textures.size() >= 1 &&
              cmd.textures.front() ==
                  (primitiveResources
                       ? primitiveResources->baseColorTexture.texture
                       : nullptr) &&
              cmd.uniforms.count("u_hasBaseColorTexture") &&
              cmd.uniforms.at("u_hasBaseColorTexture").front() == 1.0f &&
              cmd.uniforms.count("u_textureCoordSets") &&
              cmd.uniforms.at("u_textureCoordSets").size() == 4 &&
              cmd.uniforms.at("u_textureCoordSets")[0] == 1.0f,
          "Tileset: glTF draw command binds baseColorTexture with TEXCOORD_1");
    check(cmd.uniforms.count("u_baseColorTexOffsetScale") &&
              cmd.uniforms.at("u_baseColorTexOffsetScale").size() == 4 &&
              std::abs(cmd.uniforms.at("u_baseColorTexOffsetScale")[0] - 0.25f) <
                  1e-6f &&
              std::abs(cmd.uniforms.at("u_baseColorTexOffsetScale")[1] - 0.5f) <
                  1e-6f &&
              std::abs(cmd.uniforms.at("u_baseColorTexOffsetScale")[2] - 2.0f) <
                  1e-6f &&
              std::abs(cmd.uniforms.at("u_baseColorTexOffsetScale")[3] - 3.0f) <
                  1e-6f &&
              cmd.uniforms.count("u_baseColorTexRotationSinCos") &&
              cmd.uniforms.at("u_baseColorTexRotationSinCos").size() == 2 &&
              std::abs(cmd.uniforms.at("u_baseColorTexRotationSinCos")[0] - 1.0f) <
                  1e-6f &&
              std::abs(cmd.uniforms.at("u_baseColorTexRotationSinCos")[1]) <
                  1e-6f,
          "Tileset: glTF draw command uploads KHR_texture_transform uniforms");
    check(cmd.blend &&
              !cmd.depthWrite &&
              cmd.uniforms.count("u_renderOpacity") &&
              std::abs(cmd.uniforms.at("u_renderOpacity").front() - 0.5f) <
                  1e-6f,
          "Tileset: glTF draw command applies LOD transition opacity");
    check(cmd.uniforms.count("u_modelOrigin") &&
              cmd.uniforms.at("u_modelOrigin").size() == 3,
          "Tileset: glTF draw command exposes RTC model origin to Scene MVP");
    check(cmd.hasWorldSortCenter &&
              std::abs(cmd.worldSortCenter[0] -
                       (primitiveResources
                            ? primitiveResources->sortCenterEcef.x()
                            : 0.0)) <
                  1e-9 &&
              std::abs(cmd.worldSortCenter[1] -
                       (primitiveResources
                            ? primitiveResources->sortCenterEcef.y()
                            : 0.0)) <
                  1e-9 &&
              std::abs(cmd.worldSortCenter[2] -
                       (primitiveResources
                            ? primitiveResources->sortCenterEcef.z()
                            : 0.0)) <
                  1e-9 &&
              std::abs(cmd.worldSortCenter[0] - (1.0 / 3.0)) < 1e-9 &&
              std::abs(cmd.worldSortCenter[1] - (1.0 / 3.0)) < 1e-9 &&
              std::abs(cmd.worldSortCenter[2]) < 1e-9,
          "Tileset: glTF draw command carries primitive world center for transparent sorting");
}
void testTilesetGltfDrawCommandBindsMappedRasterOverlays() {
    auto overlayOptions = makeRasterOverlayOptions();
    overlayOptions.opacity = 0.42f;
    auto overlay = std::make_unique<RasterOverlay>(
        std::make_unique<DebugImageryProvider>(),
        TileScheme::createXYZWebMercator(),
        overlayOptions);
    ActivatedRasterOverlay activated(*overlay);
    DummyRenderDevice device;
    device.allowTextureCreation = true;
    auto scheme = TileScheme::createGeographicTMS();
    auto contentProvider =
        std::make_unique<ManualCompletionContentProvider>(
            TileKey{"Geographic-TMS", 0, 0, 0});
    contentProvider->ownsTerrainQuadtree = true;
    Tileset tileset(
        std::move(scheme),
        {&activated},
        &device,
        TilesetOptions{},
        std::move(contentProvider));
    const TileKey rootKey{"Geographic-TMS", 0, 0, 0};
    TilesetTile* root = TilesetTestAccess::ensureTile(tileset, rootKey);
    check(root != nullptr,
          "Tileset: glTF mapped raster root tile is created");
    if (!root) return;
    const Rectangle geometryRectangle =
        Rectangle::fromDegrees(-10.0, -5.0, 2.0, 7.0);
    root->content.renderContent.setSurfaceMesh(
        std::make_unique<SurfaceTileMesh>(
            TileSurface::buildEllipsoidMesh(geometryRectangle, 4)));
    root->content.renderContent.setMeshReady(true);
    root->content.renderContent.setSurfaceSource(
        SurfaceDrawableSource::HeightmapTerrain);
    root->content.renderContent.setRetainedHeightmap(
        makeFlatHeightmap(999.0f));
    check(root->content.renderContent.hasSurfaceMesh() &&
              root->content.renderContent.hasRetainedHeightmap(),
          "Tileset: glTF mapped raster fixture starts with stale surface and heightmap residue");
    if (!root->content.renderContent.hasSurfaceMesh() ||
        !root->content.renderContent.hasRetainedHeightmap()) {
        return;
    }
    auto model = makeTexturedTriangleGltfModel();
    model->rasterOverlayDetails.rasterOverlayProjections = {
        RasterOverlayProjection::Geographic,
        RasterOverlayProjection::WebMercator};
    model->rasterOverlayDetails.rasterOverlayRectangles = {
        Rectangle{},
        projectForProvider(*activated.ensureTileProvider(&device),
                           geometryRectangle)};
    model->rasterOverlayDetails.boundingRegion = {
        geometryRectangle,
        0.0,
        0.0};
    root->content.renderContent.prepareGltfContent(
        std::move(model),
        Mat4::identity());
    root->bounds = geometryRectangle;
    root->geometricError = 100.0;
    root->content.contentKind = TileContentKind::Render;
    root->content.loadState = TileLoadState::ContentLoaded;
    auto staleHeightmap = makeFlatHeightmap(999.0f);
    staleHeightmap->metadataAvailability.resize(4);
    TilesetTestAccess::putTerrainCache(
        tileset,
        rootKey,
        std::move(staleHeightmap));
    Renderer renderer(nullptr);
    RenderCommandList commands;
    TilesetTestAccess::buildTileDrawCommand(
        tileset,
        renderer,
        *root,
        commands,
        1.0f);
    RasterMappedToTilesetTile* mapped =
        root->rasterOverlayState.mappingAt(0);
    RasterOverlayTile* loading = mapped ? mapped->getLoadingTile() : nullptr;
    check(mapped != nullptr && loading != nullptr,
          "Tileset: glTF mapped raster draw path creates a loading mapping");
    if (!mapped || !loading) return;
    loading->setTexture(std::make_unique<DummyTexture>(4, 4));
    loading->setMoreDetailAvailable(RasterOverlayTile::MoreDetailAvailable::No);
    commands.clear();
    TilesetTestAccess::buildTileDrawCommand(
        tileset,
        renderer,
        *root,
        commands,
        1.0f);
    check(commands.size() == 1,
          "Tileset: glTF mapped raster emits one primitive command");
    if (commands.empty()) return;
    const RenderCommand& cmd = commands.front();
    check(cmd.kind == RenderCommandKind::GltfPrimitive &&
              root->content.renderContent.hasGltfModel() &&
              !root->content.renderContent.hasSurfaceMesh() &&
              !root->content.renderContent.hasRetainedHeightmap() &&
              root->content.renderContent.surfaceVertexBuffer() == nullptr &&
              root->content.renderContent.surfaceIndexBuffer() == nullptr &&
              TilesetTestAccess::hasTerrainCache(tileset, rootKey) &&
              cmd.gltfRasterOverlayTextureCount == 1 &&
              cmd.textures.size() >
                  static_cast<size_t>(kGltfRasterOverlayTextureBase) &&
              cmd.textures[0] != nullptr &&
              cmd.textures[kGltfRasterOverlayTextureBase] ==
                  loading->getTexture(),
          "Tileset: glTF mapped raster clears stale surface residue, ignores stale heightmap cache, and uses texture slot 15 without replacing material slot 0");
    check(cmd.gltfRasterOverlayTexCoordSets[0] == 1.0f &&
              cmd.uniforms.count("u_mappedRasterTexCoordSet0") &&
              cmd.uniforms.at("u_mappedRasterTexCoordSet0").front() == 1.0f,
          "Tileset: glTF mapped raster uses the matching _CESIUMOVERLAY texture coordinate ID");
    check(std::abs(cmd.gltfRasterOverlayTileUvs[0][0] -
                   mapped->getTranslationU()) < 1e-6f &&
              std::abs(cmd.gltfRasterOverlayTileUvs[0][1] -
                       mapped->getTranslationV()) < 1e-6f &&
              std::abs(cmd.gltfRasterOverlayTileUvs[0][2] -
                       mapped->getScaleU()) < 1e-6f &&
              std::abs(cmd.gltfRasterOverlayTileUvs[0][3] -
                       mapped->getScaleV()) < 1e-6f &&
              cmd.uniforms.count("u_mappedRasterTileUV0") &&
              cmd.uniforms.at("u_mappedRasterTileUV0").size() == 4,
          "Tileset: glTF mapped raster uploads translation and scale");
    check(std::abs(cmd.gltfRasterOverlayOpacities[0] - overlayOptions.opacity) <
              1e-6f &&
              cmd.uniforms.count("u_mappedRasterOpacity0") &&
              std::abs(cmd.uniforms.at("u_mappedRasterOpacity0").front() -
                       overlayOptions.opacity) < 1e-6f,
          "Tileset: glTF mapped raster preserves overlay opacity");
    check(!cmd.resourceKeepAlive.empty(),
          "Tileset: glTF mapped raster command retains raster tile resources");
}
void testTilesetGltfDrawCommandBindsTerrainWaterMask() {
    auto overlayOptions = makeRasterOverlayOptions();
    auto overlay = std::make_unique<RasterOverlay>(
        std::make_unique<DebugImageryProvider>(),
        TileScheme::createXYZWebMercator(),
        overlayOptions);
    ActivatedRasterOverlay activated(*overlay);
    DummyRenderDevice device;
    device.allowTextureCreation = true;
    auto scheme = TileScheme::createGeographicTMS();
    Tileset tileset(
        std::move(scheme),
        {&activated},
        &device,
        TilesetOptions{});
    const TileKey rootKey{"Geographic-TMS", 0, 0, 0};
    TilesetTile* root = TilesetTestAccess::ensureTile(tileset, rootKey);
    check(root != nullptr,
          "Tileset: glTF terrain water mask root tile is created");
    if (!root) return;
    const Rectangle geometryRectangle =
        Rectangle::fromDegrees(-10.0, -5.0, 2.0, 7.0);
    auto model = makeTexturedTriangleGltfModel();
    model->rasterOverlayDetails.rasterOverlayProjections = {
        RasterOverlayProjection::Geographic,
        RasterOverlayProjection::WebMercator};
    model->rasterOverlayDetails.rasterOverlayRectangles = {
        Rectangle{},
        projectForProvider(*activated.ensureTileProvider(&device),
                           geometryRectangle)};
    model->rasterOverlayDetails.boundingRegion = {
        geometryRectangle,
        0.0,
        0.0};
    WaterMask waterMask;
    waterMask.allLand = false;
    waterMask.allWater = false;
    waterMask.data.assign(256u * 256u * 4u, 127u);
    waterMask.translationX = 0.25;
    waterMask.translationY = 0.5;
    waterMask.scale = 0.5;
    GltfTexture waterMaskTexture;
    waterMaskTexture.image.width = 256;
    waterMaskTexture.image.height = 256;
    waterMaskTexture.image.channels = 1;
    waterMaskTexture.image.pixels.assign(256u * 256u, 127u);
    waterMaskTexture.sampler.wrapS = GltfTextureWrap::ClampToEdge;
    waterMaskTexture.sampler.wrapT = GltfTextureWrap::ClampToEdge;
    waterMaskTexture.sampler.mipmap = false;
    model->terrainWaterMaskTextureIndex = model->textures.size();
    model->textures.push_back(std::move(waterMaskTexture));
    model->primitives.front().hasTerrainWaterMaskMetadata = true;
    model->primitives.front().terrainOnlyLand = false;
    model->primitives.front().terrainOnlyWater = false;
    model->primitives.front().terrainWaterMaskTextureIndex =
        model->terrainWaterMaskTextureIndex;
    model->primitives.front().terrainWaterMaskTranslationX =
        waterMask.translationX;
    model->primitives.front().terrainWaterMaskTranslationY =
        waterMask.translationY;
    model->primitives.front().terrainWaterMaskScale = waterMask.scale;
    root->content.renderContent.prepareGltfContent(
        std::move(model),
        Mat4::identity());
    root->bounds = geometryRectangle;
    root->geometricError = 100.0;
    root->content.contentKind = TileContentKind::Render;
    root->content.loadState = TileLoadState::ContentLoaded;
    root->rasterOverlayState.mappings().resize(1);
    TilesetTestAccess::prefetchRasterOverlays(tileset, *root);
    RasterMappedToTilesetTile* mapped =
        root->rasterOverlayState.mappings()[0].get();
    RasterOverlayTile* loading = mapped ? mapped->getLoadingTile() : nullptr;
    check(mapped != nullptr && loading != nullptr,
          "Tileset: glTF terrain water mask creates mapped raster");
    if (!mapped || !loading) return;
    loading->setTexture(std::make_unique<DummyTexture>(4, 4));
    loading->setMoreDetailAvailable(RasterOverlayTile::MoreDetailAvailable::No);
    TilesetTestAccess::prefetchRasterOverlays(tileset, *root);
    Renderer renderer(nullptr);
    RenderCommandList commands;
    TilesetTestAccess::buildTileDrawCommand(
        tileset,
        renderer,
        *root,
        commands,
        1.0f);
    check(commands.size() == 1,
          "Tileset: glTF terrain water mask emits one primitive command");
    if (commands.empty()) return;
    const RenderCommand& cmd = commands.front();
    check(cmd.kind == RenderCommandKind::GltfPrimitive &&
              cmd.textures.size() >
                  static_cast<size_t>(kGltfWaterMaskTextureSlot) &&
              cmd.textures[0] != nullptr &&
              cmd.textures[kGltfRasterOverlayTextureBase] ==
                  loading->getTexture() &&
              cmd.textures[kGltfWaterMaskTextureSlot] != nullptr,
          "Tileset: glTF terrain water mask uses slot 19 without replacing material or raster overlays");
    check(cmd.gltfHasWaterMask == 1.0f &&
              cmd.gltfWaterMaskState[0] == 0.0f &&
              cmd.gltfWaterMaskState[1] == 0.0f &&
              cmd.gltfWaterMaskState[2] == 1.0f &&
              std::abs(cmd.gltfWaterMaskTranslationScale[0] - 0.25f) <
                  1e-6f &&
              std::abs(cmd.gltfWaterMaskTranslationScale[1] - 0.5f) <
                  1e-6f &&
              std::abs(cmd.gltfWaterMaskTranslationScale[2] - 0.5f) <
                  1e-6f,
          "Tileset: glTF terrain water mask command preserves Cesium water mask state");
    check(cmd.uniforms.count("u_gltfHasWaterMask") &&
              cmd.uniforms.at("u_gltfHasWaterMask").front() == 1.0f &&
              cmd.uniforms.count("u_gltfWaterMaskTranslationScale") &&
              cmd.uniforms.at("u_gltfWaterMaskTranslationScale").size() == 4 &&
              cmd.uniforms.count("u_gltfWaterMaskState") &&
              cmd.uniforms.at("u_gltfWaterMaskState").size() == 4,
          "Tileset: glTF terrain water mask uploads shader uniforms");
}
void testTilesetGltfTangentsUseModelLinearTransform() {
    DummyRenderDevice device;
    auto scheme = TileScheme::createGeographicTMS();
    Tileset tileset(
        std::move(scheme),
        {},
        &device,
        TilesetOptions{});
    const TileKey rootKey{"Geographic-TMS", 0, 0, 0};
    TilesetTile* root = TilesetTestAccess::ensureTile(tileset, rootKey);
    check(root != nullptr,
          "Tileset: glTF tangent transform root tile is created");
    if (!root) return;
    root->content.renderContent.prepareGltfContent(
        makeTriangleGltfModel(),
        Mat4::scale(Vec3(2.0, 1.0, 1.0)));
    GltfModel* model = root->content.renderContent.gltfContent();
    check(model != nullptr,
          "Tileset: glTF tangent transform model is retained");
    if (!model) return;
    const float diagonal = static_cast<float>(1.0 / std::sqrt(2.0));
    for (auto& tangent : model->primitives[0].vertexTangents) {
        tangent = {diagonal, diagonal, 0.0f, 1.0f};
    }
    root->content.contentKind = TileContentKind::Render;
    root->content.loadState = TileLoadState::ContentLoaded;
    Renderer renderer(nullptr);
    RenderCommandList commands;
    TilesetTestAccess::buildTileDrawCommand(
        tileset,
        renderer,
        *root,
        commands,
        1.0f);
    check(!commands.empty() &&
              root->content.renderContent.gltfPrimitiveResourceCount() == 1u,
          "Tileset: glTF tangent transform uploads primitive resources");
    if (commands.empty()) return;
    const auto* uploadedVertices =
        dynamic_cast<const DummyBuffer*>(commands.front().vertexBuffer);
    bool tangentUsesModelLinear = false;
    if (uploadedVertices && uploadedVertices->bytes().size() >= 120u) {
        std::array<float, 30> values{};
        std::memcpy(
            values.data(),
            uploadedVertices->bytes().data(),
            values.size() * sizeof(float));
        tangentUsesModelLinear =
            std::abs(values[14] - 0.8944272f) < 1e-5f &&
            std::abs(values[15] - 0.4472136f) < 1e-5f &&
            std::abs(values[16]) < 1e-6f &&
            std::abs(values[17] - 1.0f) < 1e-6f;
    }
    check(tangentUsesModelLinear,
          "Tileset: glTF tangents use model linear transform under non-uniform scale");
}
