        std::lock_guard<std::mutex> lock(lifecycle.mutex());
        lifecycle.pendingLoads().addTerminalResult(PendingTileLoad{TileLoadDomain::TerrainContent,
                firstKey,
                "first-terminal",
                TileLoadPriorityGroup::Normal,
                0.0,
                TileLoadStatus::RetryLater});
