void testTilesetUpsampledChildBuildsGltfFromGltfParent() {
    auto provider = std::make_unique<SparseTerrainProvider>();
    SparseTerrainProvider* rawProvider = provider.get();
    DummyRenderDevice device;
    auto scheme = TileScheme::createGeographicTMS();
    Tileset tileset = TilesetTestAccess::makeLegacyTerrainTileset(
        std::move(provider),
        std::move(scheme),
        {},
        &device,
        TilesetOptions{});
    const TileKey rootKey{"Geographic-TMS", 0, 0, 0};
    TilesetTile* root = TilesetTestAccess::ensureTile(tileset, rootKey);
    check(root != nullptr,
          "Tileset: glTF-parent upsample root tile is created");
    if (!root) return;
    auto parentModel = makeQuadTerrainGltfModel(root->bounds);
    const Rectangle parentOverlayRectangle =
        Rectangle::fromDegrees(10.0, 20.0, 18.0, 28.0);
    parentModel->rasterOverlayDetails.rasterOverlayProjections = {
        RasterOverlayProjection::Geographic};
    parentModel->rasterOverlayDetails.rasterOverlayRectangles = {
        parentOverlayRectangle};
    parentModel->rasterOverlayDetails.boundingRegion = {
        root->bounds,
        -5.0,
        25.0};
    root->content.renderContent.prepareGltfContent(
        std::move(parentModel),
        Mat4::identity());
    root->content.renderContent.setTerrainRenderContent(true);
    root->markRenderContentDone();
    check(!root->content.renderContent.hasGltfResources(),
          "Tileset: glTF-parent source does not need renderer resources before upsample");
    TilesetTestAccess::ensureTileChildren(tileset, *root);
    check(root->children.size() == 4,
          "Tileset: glTF-parent upsample setup creates partial-availability children");
    if (root->children.size() < 2 || !root->children[1]) return;
    TilesetTile* child = root->children[1];
    check(child->content.isTerrainAvailabilityUpsample(),
          "Tileset: glTF-parent child is marked as upsampled terrain");
    TilesetTestAccess::requestMissingTile(tileset, child->key);
    check(child->content.loadState == TileLoadState::ContentLoading &&
              tileset.loadDiagnostics().pendingContentUploads == 0 &&
              tileset.loadDiagnostics().pendingGltfTerrainUploads == 1 &&
              rawProvider->requestCount == 0,
          "Tileset: glTF-parent child enters local glTF terrain upload without provider request");
    TilesetTestAccess::processPendingUploads(tileset);
    const GltfModel* childModel =
        child->content.renderContent.gltfModelForRead();
    check(child->content.loadState == TileLoadState::Done &&
              child->content.renderContent.hasGltfContent() &&
              child->content.renderContent.hasGltfResources() &&
              !child->content.renderContent.hasSurfaceMesh() &&
              TilesetTestAccess::isTileRenderable(tileset, *child),
          "Tileset: glTF-parent upsampled child becomes renderable as glTF content");
    if (!childModel || childModel->primitives.empty()) return;
    bool clippedToSouthEast = true;
    const GltfPrimitive& primitive = childModel->primitives.front();
    check(childModel->nodes.size() == 1 &&
              childModel->sceneRootNodes.size() == 1 &&
              childModel->sceneRootNodes.front() == 0 &&
              primitive.runtime.nodeIndex == 0,
          "Tileset: glTF-parent upsampled child keeps terrain scene root and node binding");
    check(primitive.runtime.baseVertices.size() == primitive.vertices.size(),
          "Tileset: glTF-parent upsampled child keeps runtime base vertices");
    bool runtimeVerticesAreNodeLocal = true;
    if (!childModel->nodes.empty() &&
        primitive.runtime.baseVertices.size() == primitive.vertices.size()) {
        const Mat4 inverseNodeTransform =
            childModel->nodes.front().globalTransform.inverse();
        for (size_t i = 0; i < primitive.vertices.size(); ++i) {
            const Vec3 expectedLocal =
                inverseNodeTransform.transformPoint(
                    primitive.vertices[i].positionEcef);
            runtimeVerticesAreNodeLocal =
                runtimeVerticesAreNodeLocal &&
                primitive.runtime.baseVertices[i].positionEcef.distanceTo(
                    expectedLocal) < 1e-12;
        }
    } else {
        runtimeVerticesAreNodeLocal = false;
    }
    check(runtimeVerticesAreNodeLocal,
          "Tileset: glTF-parent upsampled child stores node-local runtime vertices like Cesium native");
    for (const SurfaceVertex& vertex : primitive.vertices) {
        clippedToSouthEast =
            clippedToSouthEast &&
            vertex.uv[0] >= 0.5f &&
            vertex.uv[1] <= 0.5f;
    }
    check(clippedToSouthEast,
          "Tileset: glTF-parent upsample clips child geometry to child raster quadrant");
    const Rectangle* childOverlay =
        childModel->rasterOverlayDetails.findRectangleForOverlayProjection(
            RasterOverlayProjection::Geographic);
    const auto interpolateOverlay = [](const Rectangle& parentBounds,
                                       const Rectangle& childBounds,
                                       const Rectangle& parentOverlay) {
        const auto mix = [](double a, double b, double t) {
            return a + (b - a) * t;
        };
        const double westT =
            (childBounds.west() - parentBounds.west()) /
            parentBounds.width();
        const double eastT =
            (childBounds.east() - parentBounds.west()) /
            parentBounds.width();
        const double southT =
            (childBounds.south() - parentBounds.south()) /
            parentBounds.height();
        const double northT =
            (childBounds.north() - parentBounds.south()) /
            parentBounds.height();
        return Rectangle(
            mix(parentOverlay.west(), parentOverlay.east(), westT),
            mix(parentOverlay.south(), parentOverlay.north(), southT),
            mix(parentOverlay.west(), parentOverlay.east(), eastT),
            mix(parentOverlay.south(), parentOverlay.north(), northT));
    };
    const Rectangle expectedChildOverlay =
        interpolateOverlay(root->bounds, child->bounds, parentOverlayRectangle);
    check(childOverlay &&
              childOverlay->equalsEpsilon(expectedChildOverlay, 1e-12) &&
              childModel->rasterOverlayDetails.boundingRegion.rectangle ==
                  child->bounds &&
              std::abs(childModel->rasterOverlayDetails.boundingRegion
                           .minimumHeight -
                       -5.0) < 1e-12 &&
              std::abs(childModel->rasterOverlayDetails.boundingRegion
                           .maximumHeight -
                       25.0) < 1e-12,
          "Tileset: glTF-parent upsampled child derives raster overlay details from parent content");
}
void testTilesetUpsampledChildUsesAvailableRasterProjectionTexcoord() {
    auto provider = std::make_unique<SparseTerrainProvider>();
    SparseTerrainProvider* rawProvider = provider.get();
    DummyRenderDevice device;
    auto scheme = TileScheme::createGeographicTMS();
    Tileset tileset = TilesetTestAccess::makeLegacyTerrainTileset(
        std::move(provider),
        std::move(scheme),
        {},
        &device,
        TilesetOptions{});
    const TileKey rootKey{"Geographic-TMS", 0, 0, 0};
    TilesetTile* root = TilesetTestAccess::ensureTile(tileset, rootKey);
    check(root != nullptr,
          "Tileset: WebMercator glTF-parent upsample root tile is created");
    if (!root) return;
    auto parentModel = makeWebMercatorQuadTerrainGltfModel(root->bounds);
    const Rectangle parentWebMercatorOverlay(100.0, 200.0, 180.0, 280.0);
    parentModel->rasterOverlayDetails.rasterOverlayRectangles[0] =
        root->bounds;
    parentModel->rasterOverlayDetails.rasterOverlayRectangles[1] =
        parentWebMercatorOverlay;
    parentModel->rasterOverlayDetails.boundingRegion = {
        root->bounds,
        -8.0,
        45.0};
    RasterOverlayDetails parentOverlayDetails =
        parentModel->rasterOverlayDetails;
    root->content.renderContent.prepareGltfContent(
        std::move(parentModel),
        Mat4::identity());
    root->content.renderContent.setTerrainRenderContent(true);
    root->markRenderContentDone();
    check(!root->content.renderContent.hasGltfResources(),
          "Tileset: WebMercator glTF-parent source does not need renderer resources before upsample");
    TilesetTestAccess::ensureTileChildren(tileset, *root);
    check(root->children.size() == 4,
          "Tileset: WebMercator glTF-parent upsample setup creates children");
    if (root->children.size() < 3 || !root->children[2]) return;
    auto imageryScheme = TileScheme::createXYZWebMercator();
    DebugImageryProvider imagery;
    RasterOverlayTileProvider rasterProvider(
        imagery,
        *imageryScheme,
        nullptr);
    RasterMappedToTilesetTile& mapped =
        root->rasterOverlayState.ensureMapping(0);
    std::vector<RasterOverlayProjection> missingProjections;
    mapped.update(
        root->key,
        parentOverlayDetails,
        512.0,
        512.0,
        rasterProvider,
        nullptr,
        missingProjections,
        nullptr,
        0);
    RasterOverlayTile* loadingTile = mapped.getLoadingTile();
    if (!loadingTile) return;
    loadingTile->setTexture(std::make_unique<DummyTexture>(8, 4));
    loadingTile->setMoreDetailAvailable(
        RasterOverlayTile::MoreDetailAvailable::Yes);
    mapped.update(
        root->key,
        parentOverlayDetails,
        512.0,
        512.0,
        rasterProvider,
        nullptr,
        missingProjections,
        nullptr,
        0);
    check(mapped.isMoreDetailAvailable() &&
              mapped.getTextureCoordinateID() == 1,
          "Tileset: WebMercator glTF-parent source mapping marks projection texcoord as more-detail");
    TilesetTile* child = root->children[2];
    child->content.markRasterDetailUpsample();
    TilesetTestAccess::requestMissingTile(tileset, child->key);
    check(child->content.loadState == TileLoadState::ContentLoading &&
              tileset.loadDiagnostics().pendingContentUploads == 0 &&
              tileset.loadDiagnostics().pendingGltfTerrainUploads == 1 &&
              rawProvider->requestCount == 0,
          "Tileset: WebMercator glTF-parent child queues local glTF terrain upsample");
    TilesetTestAccess::processPendingUploads(tileset);
    const GltfModel* childModel =
        child->content.renderContent.gltfModelForRead();
    check(child->content.loadState == TileLoadState::Done &&
              childModel != nullptr &&
              child->content.renderContent.hasGltfResources() &&
              !child->content.renderContent.hasSurfaceMesh(),
          "Tileset: WebMercator glTF-parent upsample uses available overlay texcoord");
    if (!childModel || childModel->primitives.empty()) return;
    const GltfPrimitive& primitive = childModel->primitives.front();
    bool clippedToNorthWestTexcoord = true;
    for (const auto& texCoord : primitive.vertexTexCoords[1]) {
        clippedToNorthWestTexcoord =
            clippedToNorthWestTexcoord &&
            texCoord[0] <= 0.5f &&
            texCoord[1] >= 0.5f;
    }
    check(clippedToNorthWestTexcoord,
          "Tileset: WebMercator glTF-parent clips with projection texcoord");
    const Rectangle* childOverlay =
        childModel->rasterOverlayDetails.findRectangleForOverlayProjection(
            RasterOverlayProjection::WebMercator);
    const auto mix = [](double a, double b, double t) {
        return a + (b - a) * t;
    };
    const Rectangle projectedParentBounds = projectRectangleSimple(
        WebMercatorProjection(Ellipsoid::WGS84()),
        root->bounds);
    const Rectangle projectedChildBounds = projectRectangleSimple(
        WebMercatorProjection(Ellipsoid::WGS84()),
        child->bounds);
    const double westT =
        (projectedChildBounds.west() - projectedParentBounds.west()) /
        projectedParentBounds.width();
    const double eastT =
        (projectedChildBounds.east() - projectedParentBounds.west()) /
        projectedParentBounds.width();
    const double southT =
        (projectedChildBounds.south() - projectedParentBounds.south()) /
        projectedParentBounds.height();
    const double northT =
        (projectedChildBounds.north() - projectedParentBounds.south()) /
        projectedParentBounds.height();
    const Rectangle expectedChildOverlay(
        mix(parentWebMercatorOverlay.west(), parentWebMercatorOverlay.east(), westT),
        mix(parentWebMercatorOverlay.south(), parentWebMercatorOverlay.north(), southT),
        mix(parentWebMercatorOverlay.west(), parentWebMercatorOverlay.east(), eastT),
        mix(parentWebMercatorOverlay.south(), parentWebMercatorOverlay.north(), northT));
    check(childOverlay &&
              childOverlay->equalsEpsilon(expectedChildOverlay, 1e-12) &&
              childModel->rasterOverlayDetails.boundingRegion.rectangle ==
                  child->bounds &&
              std::abs(childModel->rasterOverlayDetails.boundingRegion
                           .minimumHeight -
                       -8.0) < 1e-12 &&
              std::abs(childModel->rasterOverlayDetails.boundingRegion
                           .maximumHeight -
                       45.0) < 1e-12,
          "Tileset: WebMercator glTF-parent derives child projection overlay details from parent");
}
